-- Migration 0002: Teel Ridge Book Club application schema.
-- Conventions:
--   * ids are random text ids generated by the Worker
--   * timestamps are ISO-8601 UTC text (lexicographically sortable)
--   * shared club records carry created_by/updated_by/version for optimistic concurrency
--   * personal records carry user_id and are only mutable by that user (enforced in the API)

-- ---------------------------------------------------------------------------
-- Member profile, avatar and settings
-- ---------------------------------------------------------------------------
CREATE TABLE profiles (
  user_id TEXT PRIMARY KEY NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  bio TEXT,
  location TEXT,
  pronouns TEXT,
  favorite_genres TEXT,
  default_visibility TEXT NOT NULL DEFAULT 'club' CHECK (default_visibility IN ('private', 'club')),
  avatar_version INTEGER NOT NULL DEFAULT 0,
  privacy_accepted_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE avatars (
  user_id TEXT PRIMARY KEY NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  content_type TEXT NOT NULL CHECK (content_type IN ('image/webp', 'image/jpeg', 'image/png')),
  data BLOB NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE notification_preferences (
  user_id TEXT PRIMARY KEY NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  inapp_direct_messages INTEGER NOT NULL DEFAULT 1,
  inapp_recommendations INTEGER NOT NULL DEFAULT 1,
  inapp_club_updates INTEGER NOT NULL DEFAULT 1,
  inapp_reactions INTEGER NOT NULL DEFAULT 1,
  email_club_updates INTEGER NOT NULL DEFAULT 0,
  email_recommendations INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Catalogue: works and editions (canonical per edition, ISBN-13 preferred)
-- ---------------------------------------------------------------------------
CREATE TABLE books (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL,
  primary_author TEXT,
  -- Normalised "title|author" key used to group editions of the same work.
  work_key TEXT NOT NULL,
  openlibrary_work_id TEXT,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX books_work_key_idx ON books (work_key);
CREATE UNIQUE INDEX books_openlibrary_work_idx ON books (openlibrary_work_id) WHERE openlibrary_work_id IS NOT NULL;

CREATE TABLE book_editions (
  id TEXT PRIMARY KEY NOT NULL,
  book_id TEXT NOT NULL REFERENCES books (id) ON DELETE CASCADE,
  isbn13 TEXT,
  isbn10 TEXT,
  title TEXT NOT NULL,
  subtitle TEXT,
  authors TEXT NOT NULL DEFAULT '[]', -- JSON array of author names
  publisher TEXT,
  published_date TEXT,
  published_year INTEGER,
  format TEXT NOT NULL DEFAULT 'unknown'
    CHECK (format IN ('hardcover', 'paperback', 'ebook', 'audiobook', 'other', 'unknown')),
  language TEXT,
  page_count INTEGER,
  description TEXT,
  cover_url TEXT,
  cover_url_large TEXT,
  google_books_id TEXT,
  openlibrary_edition_id TEXT,
  goodreads_book_id TEXT,
  source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('google_books', 'open_library', 'manual', 'goodreads')),
  search_text TEXT NOT NULL DEFAULT '', -- lowercased title + subtitle + authors for simple local search
  version INTEGER NOT NULL DEFAULT 1,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX book_editions_isbn13_idx ON book_editions (isbn13) WHERE isbn13 IS NOT NULL;
CREATE INDEX book_editions_isbn10_idx ON book_editions (isbn10) WHERE isbn10 IS NOT NULL;
CREATE UNIQUE INDEX book_editions_google_idx ON book_editions (google_books_id) WHERE google_books_id IS NOT NULL;
CREATE UNIQUE INDEX book_editions_openlibrary_idx ON book_editions (openlibrary_edition_id) WHERE openlibrary_edition_id IS NOT NULL;
CREATE INDEX book_editions_goodreads_idx ON book_editions (goodreads_book_id) WHERE goodreads_book_id IS NOT NULL;
CREATE INDEX book_editions_book_idx ON book_editions (book_id);

-- Shared club genres/tags.
CREATE TABLE genres (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at TEXT,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX genres_slug_idx ON genres (slug);

-- Genres are attached to the work, so every edition of a book shares them.
CREATE TABLE book_genres (
  book_id TEXT NOT NULL REFERENCES books (id) ON DELETE CASCADE,
  genre_id TEXT NOT NULL REFERENCES genres (id) ON DELETE CASCADE,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (book_id, genre_id)
);
CREATE INDEX book_genres_genre_idx ON book_genres (genre_id);

-- ---------------------------------------------------------------------------
-- Personal reading data
-- ---------------------------------------------------------------------------
CREATE TABLE user_books (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  edition_id TEXT NOT NULL REFERENCES book_editions (id) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK (status IN ('tbr', 'reading', 'finished', 'abandoned')),
  started_at TEXT,
  finished_at TEXT,
  current_page INTEGER CHECK (current_page IS NULL OR current_page >= 0),
  progress_percent INTEGER CHECK (progress_percent IS NULL OR (progress_percent BETWEEN 0 AND 100)),
  visibility TEXT NOT NULL DEFAULT 'club' CHECK (visibility IN ('private', 'club')),
  notes TEXT,
  shelves TEXT NOT NULL DEFAULT '[]', -- JSON array of personal shelf names (e.g. from Goodreads)
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (user_id, edition_id)
);
CREATE INDEX user_books_user_status_idx ON user_books (user_id, status, updated_at);
CREATE INDEX user_books_user_finished_idx ON user_books (user_id, finished_at) WHERE status = 'finished';
CREATE INDEX user_books_edition_idx ON user_books (edition_id);
CREATE INDEX user_books_recent_idx ON user_books (updated_at);

CREATE TABLE reviews (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  edition_id TEXT NOT NULL REFERENCES book_editions (id) ON DELETE CASCADE,
  body TEXT NOT NULL DEFAULT '',
  sentiment TEXT NOT NULL CHECK (sentiment IN ('loved', 'liked', 'mixed', 'disliked', 'hated')),
  visibility TEXT NOT NULL DEFAULT 'club' CHECK (visibility IN ('private', 'club')),
  contains_spoilers INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (user_id, edition_id)
);
CREATE INDEX reviews_edition_idx ON reviews (edition_id, created_at);
CREATE INDEX reviews_recent_idx ON reviews (created_at);

CREATE TABLE review_reactions (
  review_id TEXT NOT NULL REFERENCES reviews (id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  reaction TEXT NOT NULL CHECK (reaction IN ('like', 'insightful', 'funny', 'agree')),
  created_at TEXT NOT NULL,
  PRIMARY KEY (review_id, user_id, reaction)
);
CREATE INDEX review_reactions_user_idx ON review_reactions (user_id);

CREATE TABLE quotes (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  edition_id TEXT NOT NULL REFERENCES book_editions (id) ON DELETE CASCADE,
  text TEXT NOT NULL,
  location TEXT,
  note TEXT,
  visibility TEXT NOT NULL DEFAULT 'club' CHECK (visibility IN ('private', 'club')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX quotes_user_idx ON quotes (user_id, created_at);
CREATE INDEX quotes_edition_idx ON quotes (edition_id, created_at);

CREATE TABLE personal_reading_goals (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  year INTEGER NOT NULL,
  target INTEGER NOT NULL CHECK (target > 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (user_id, year)
);

CREATE TABLE recommendations (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  edition_id TEXT NOT NULL REFERENCES book_editions (id) ON DELETE CASCADE,
  -- NULL means "recommended to the whole club".
  recipient_user_id TEXT REFERENCES "user" ("id") ON DELETE CASCADE,
  note TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK (recipient_user_id IS NULL OR recipient_user_id <> user_id)
);
CREATE INDEX recommendations_recent_idx ON recommendations (created_at);
CREATE INDEX recommendations_recipient_idx ON recommendations (recipient_user_id, created_at);
CREATE INDEX recommendations_user_idx ON recommendations (user_id, created_at);

-- ---------------------------------------------------------------------------
-- Shared club data (any member may create/edit/reorder/archive)
-- ---------------------------------------------------------------------------
CREATE TABLE club_annual_goals (
  id TEXT PRIMARY KEY NOT NULL,
  year INTEGER NOT NULL UNIQUE,
  target INTEGER NOT NULL CHECK (target > 0),
  version INTEGER NOT NULL DEFAULT 1,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE club_annual_books (
  id TEXT PRIMARY KEY NOT NULL,
  year INTEGER NOT NULL,
  edition_id TEXT NOT NULL REFERENCES book_editions (id) ON DELETE CASCADE,
  position INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'current', 'completed')),
  completed_at TEXT,
  note TEXT,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at TEXT,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX club_annual_books_unique_active_idx ON club_annual_books (year, edition_id) WHERE archived_at IS NULL;
CREATE INDEX club_annual_books_year_idx ON club_annual_books (year, position);

CREATE TABLE club_meetings (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL,
  starts_at TEXT NOT NULL,
  ends_at TEXT,
  location TEXT,
  details TEXT,
  edition_id TEXT REFERENCES book_editions (id) ON DELETE SET NULL,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at TEXT,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX club_meetings_starts_idx ON club_meetings (starts_at);

CREATE TABLE club_assignments (
  id TEXT PRIMARY KEY NOT NULL,
  edition_id TEXT NOT NULL REFERENCES book_editions (id) ON DELETE CASCADE,
  meeting_id TEXT REFERENCES club_meetings (id) ON DELETE SET NULL,
  due_date TEXT NOT NULL,
  reading_scope TEXT,
  details TEXT,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at TEXT,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX club_assignments_due_idx ON club_assignments (due_date);

CREATE TABLE club_activities (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'other' CHECK (kind IN ('event', 'discussion', 'challenge', 'other')),
  details TEXT,
  starts_at TEXT,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at TEXT,
  created_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  updated_by TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX club_activities_recent_idx ON club_activities (created_at);

-- ---------------------------------------------------------------------------
-- Messaging (authenticated only; never shareable)
-- ---------------------------------------------------------------------------
CREATE TABLE conversations (
  id TEXT PRIMARY KEY NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('club', 'direct')),
  -- For direct conversations: "<smaller user id>:<larger user id>" so a pair has exactly one conversation.
  direct_key TEXT UNIQUE,
  last_message_at TEXT,
  created_at TEXT NOT NULL,
  CHECK ((kind = 'direct' AND direct_key IS NOT NULL) OR (kind = 'club' AND direct_key IS NULL))
);

CREATE TABLE conversation_participants (
  conversation_id TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  last_read_at TEXT,
  joined_at TEXT NOT NULL,
  PRIMARY KEY (conversation_id, user_id)
);
CREATE INDEX conversation_participants_user_idx ON conversation_participants (user_id);

CREATE TABLE messages (
  id TEXT PRIMARY KEY NOT NULL,
  conversation_id TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  sender_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  -- NULL once the sender removes the message: removed text is not retained.
  body TEXT,
  created_at TEXT NOT NULL,
  edited_at TEXT,
  deleted_at TEXT,
  CHECK ((deleted_at IS NULL AND body IS NOT NULL) OR (deleted_at IS NOT NULL AND body IS NULL))
);
CREATE INDEX messages_conversation_idx ON messages (conversation_id, created_at);

-- The single main club conversation.
INSERT INTO conversations (id, kind, direct_key, last_message_at, created_at)
VALUES ('club', 'club', NULL, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));

-- ---------------------------------------------------------------------------
-- Public share links (reviews, quotes, reading lists, club list — never chats)
-- ---------------------------------------------------------------------------
CREATE TABLE share_links (
  id TEXT PRIMARY KEY NOT NULL,
  -- SHA-256 of the random URL token; the token itself is never stored.
  token_hash TEXT NOT NULL UNIQUE,
  created_by TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  resource_type TEXT NOT NULL CHECK (resource_type IN ('review', 'quote', 'reading_list', 'club_list')),
  resource_id TEXT,
  year INTEGER,
  status TEXT CHECK (status IS NULL OR status IN ('tbr', 'reading', 'finished', 'abandoned')),
  expires_at TEXT,
  revoked_at TEXT,
  view_count INTEGER NOT NULL DEFAULT 0,
  last_viewed_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX share_links_owner_idx ON share_links (created_by, created_at);

-- ---------------------------------------------------------------------------
-- In-app notifications
-- ---------------------------------------------------------------------------
CREATE TABLE notifications (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  kind TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  link TEXT,
  actor_id TEXT REFERENCES "user" ("id") ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  read_at TEXT
);
CREATE INDEX notifications_user_idx ON notifications (user_id, created_at);
CREATE INDEX notifications_unread_idx ON notifications (user_id) WHERE read_at IS NULL;

-- ---------------------------------------------------------------------------
-- Goodreads imports
-- ---------------------------------------------------------------------------
CREATE TABLE imports (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  source TEXT NOT NULL DEFAULT 'goodreads' CHECK (source IN ('goodreads')),
  status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'completed', 'failed')),
  total_rows INTEGER NOT NULL DEFAULT 0,
  created_count INTEGER NOT NULL DEFAULT 0,
  updated_count INTEGER NOT NULL DEFAULT 0,
  skipped_count INTEGER NOT NULL DEFAULT 0,
  error_count INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  completed_at TEXT
);
CREATE INDEX imports_user_idx ON imports (user_id, created_at);

-- ---------------------------------------------------------------------------
-- Infrastructure
-- ---------------------------------------------------------------------------
-- Fixed-window rate limiting counters (auth endpoints and abuse-sensitive API routes).
CREATE TABLE rate_limits (
  key TEXT PRIMARY KEY NOT NULL,
  count INTEGER NOT NULL,
  window_start INTEGER NOT NULL -- epoch milliseconds
);

-- Development-only email outbox, written ONLY when EMAIL_PROVIDER=console and
-- APP_ENV is not production (enforced in worker/email). Lets local testers and
-- the end-to-end suite open verification links without a real mail provider.
CREATE TABLE dev_outbox (
  id TEXT PRIMARY KEY NOT NULL,
  to_address TEXT NOT NULL,
  subject TEXT NOT NULL,
  text_body TEXT NOT NULL,
  html_body TEXT NOT NULL,
  created_at TEXT NOT NULL
);
